// Cloudflare Worker entry: the Next.js app (built by OpenNext) plus the jobs Vercel used to run for us.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import app from "./.open-next/worker.js";
import { imageCacheKey } from "./lib/image-cache-key";

type Env = { CRON_SECRET?: string; SITE_URL?: string };
type Ctx = { waitUntil(p: Promise<unknown>): void; passThroughOnException(): void };

export default {
  async fetch(request: Request, env: Env, ctx: Ctx): Promise<Response> {
    // pyaarse.net → www.pyaarse.net (same path and query), as on Vercel.
    const url = new URL(request.url);
    if (url.hostname === "pyaarse.net") {
      url.hostname = "www.pyaarse.net";
      return Response.redirect(url.toString(), 308);
    }
    // Resized photos: keep each one in Cloudflare's edge cache, so it's made once, not on every visit.
    const key = imageCacheKey(request);
    if (key) {
      const cache = (caches as unknown as { default: Cache }).default;
      const hit = await cache.match(key);
      if (hit) return hit;
      const res: Response = await app.fetch(request, env, ctx);
      if (res.status === 200) ctx.waitUntil(cache.put(key, res.clone()));
      return res;
    }
    return app.fetch(request, env, ctx);
  },

  // Daily at 03:00 UTC (wrangler.jsonc "triggers"): cancel unpaid orders past their time, tidy rate limits,
  // and keep the free Supabase project active. Same job and secret check as the old Vercel Cron.
  async scheduled(_event: unknown, env: Env, ctx: Ctx): Promise<void> {
    const site = env.SITE_URL || "https://www.pyaarse.net";
    const req = new Request(`${site}/api/keepalive`, { headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` } });
    ctx.waitUntil(
      app.fetch(req, env, ctx).then(async (res: Response) => console.log("[cron] keepalive", res.status, await res.text())),
    );
  },
};
